//go:build ignore

package main

import "os"

// gen_stubs.go writes temporary bootstrap stubs that allow pkg/streamplace to
// compile before cbor_gen.go exists. These are needed because lexgen generates
// union marshal code (e.g. Livestream_Activity.MarshalCBOR) that calls CBOR
// methods on variant types (Defs_ActivityGame, Defs_ActivityLabel), but those
// methods are only generated by gen.go -- which itself needs the package to
// compile. The stubs break this cycle; gen.go overwrites them in cbor_gen.go
// and the stub file is deleted before the next compilation.
const stubs = `package streamplace

import "io"

func (t *Defs_ActivityGame) MarshalCBOR(w io.Writer) error    { return nil }
func (t *Defs_ActivityGame) UnmarshalCBOR(r io.Reader) error  { return nil }
func (t *Defs_ActivityLabel) MarshalCBOR(w io.Writer) error   { return nil }
func (t *Defs_ActivityLabel) UnmarshalCBOR(r io.Reader) error { return nil }
`

func main() {
	if err := os.WriteFile("pkg/streamplace/cbor_stubs.go", []byte(stubs), 0644); err != nil {
		panic(err)
	}
}
